/**
 * v2-only package export-map gate.
 *
 * This replaces the old legacy no-growth snapshots. The v2 public package
 * should expose only deliberate supported entries and stylesheet assets.
 * Removed v1 package and subpath surfaces must not be advertised by the source
 * package contract.
 *
 * This intentionally reads packages/superdoc/package.json instead of the
 * packed fixture. The fixture is generated by earlier matrix steps and can be
 * stale when this source-only absence gate runs locally.
 */
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const CONSUMER_TYPECHECK = resolve(HERE, '..');
const REPO_ROOT = resolve(CONSUMER_TYPECHECK, '..', '..');
const SUPERDOC_PACKAGE_JSON = resolve(REPO_ROOT, 'packages/superdoc/package.json');
const SUPER_EDITOR_PACKAGE_JSON = resolve(REPO_ROOT, 'packages/super-editor/package.json');

export const FAMILY = 'v2-only-resolution';
export const DESCRIPTION = 'supported v2 package exports exist; removed v1 exports/package do not';

const SUPPORTED_EXPORTS = [
  { specifier: 'superdoc', key: '.' },
  { specifier: 'superdoc/style.css', key: './style.css' },
  { specifier: 'superdoc/style.layered.css', key: './style.layered.css' },
  // v2-native public custom-UI entries. Restored as v2-native controllers
  // (not the removed v1 editor UI subpaths); see packages/superdoc/src/public/ui.ts.
  { specifier: 'superdoc/ui', key: './ui' },
  { specifier: 'superdoc/ui/react', key: './ui/react' },
  { specifier: 'superdoc/ui/vue', key: './ui/vue' },
  // Node-only migration engine used by @superdoc/v2-collaboration-upgrade.
  { specifier: 'superdoc/collaboration-upgrade-engine', key: './collaboration-upgrade-engine' },
  // Browser Worker bootstrap for customer-owned collaboration provider adapters.
  { specifier: 'superdoc/collaboration-worker', key: './collaboration-worker' },
];

// Removed v1 subpaths that must stay absent from the v2 package contract. The
// three `headless-toolbar*` entries encode the migration-only custom-UI posture:
// v1 headless-toolbar code migrates to the canonical `superdoc/ui` /
// `superdoc/ui/react` / `superdoc/ui/vue` surfaces (above), not to a restored
// shim. Restoring any
// headless-toolbar subpath is a reviewed package-contract change that must
// update this gate deliberately.
const REMOVED_EXPORTS = [
  { specifier: 'superdoc/super-editor', key: './super-editor' },
  { specifier: 'superdoc/types', key: './types' },
  { specifier: 'superdoc/converter', key: './converter' },
  { specifier: 'superdoc/docx-zipper', key: './docx-zipper' },
  { specifier: 'superdoc/file-zipper', key: './file-zipper' },
  { specifier: 'superdoc/headless-toolbar', key: './headless-toolbar' },
  { specifier: 'superdoc/headless-toolbar/react', key: './headless-toolbar/react' },
  { specifier: 'superdoc/headless-toolbar/vue', key: './headless-toolbar/vue' },
];

function readSuperdocExports() {
  const pkg = JSON.parse(readFileSync(SUPERDOC_PACKAGE_JSON, 'utf8'));
  const exportsMap = pkg.exports && typeof pkg.exports === 'object' ? pkg.exports : {};
  return new Set(Object.keys(exportsMap));
}

/**
 * @param {{ mode: 'check' | 'write' }} opts
 * @returns {{ code: number }}
 */
export function run({ mode }) {
  if (mode === 'write') {
    console.log('[v2-only-resolution] No snapshots are written for this absence gate.');
  }

  if (!existsSync(SUPERDOC_PACKAGE_JSON)) {
    console.error(`[v2-only-resolution] Missing package contract: ${SUPERDOC_PACKAGE_JSON}`);
    return { code: 1 };
  }

  const exportKeys = readSuperdocExports();
  let failed = false;

  for (const { specifier, key } of SUPPORTED_EXPORTS) {
    if (exportKeys.has(key)) {
      console.log(`[v2-only-resolution] ${specifier}: exported as ${key}`);
    } else {
      console.error(`[v2-only-resolution] ${specifier}: expected package export ${key}, but it is absent.`);
      failed = true;
    }
  }

  for (const { specifier, key } of REMOVED_EXPORTS) {
    if (exportKeys.has(key)) {
      console.error(`[v2-only-resolution] ${specifier}: expected package export ${key} to be absent, but it exists.`);
      failed = true;
    } else {
      console.log(`[v2-only-resolution] ${specifier}: no package export ${key}`);
    }
  }

  if (existsSync(SUPER_EDITOR_PACKAGE_JSON)) {
    console.error('[v2-only-resolution] @superdoc/super-editor workspace package still exists.');
    failed = true;
  } else {
    console.log('[v2-only-resolution] @superdoc/super-editor workspace package is absent');
  }

  return { code: failed ? 1 : 0 };
}
